// CSD_RATIONALE_BEGIN
// Root-cause: The best attempt (40.8%) used `next == "<<"` for delimiter
// detection (wrong: may miss space-prefixed or split tokens) and
// `AdaptiveConstrainedStep` inside spans, which allowed the model to extend
// already-complete expressions into repetition loops (`/ 1 / 1 / 1`,
// `--1--1`). The repetition loops occur because the grammar allows indefinite
// extension of arithmetic expressions, and `AdaptiveConstrainedStep` picks
// the locally preferred token (often `/` or `-`) regardless of prior context.
//
// Fixes applied on top of the best attempt:
// 1. `RenderedEndsWith(generated, "<<")` instead of `next == "<<"`.
// 2. `RepetitionPenaltyStep(penalty=3.0)` inside spans: penalizes tokens
//    already present in `generated`, breaking `/1/1/1` and `--1--1` cycles.
// 3. Span length cap (20 tokens): if `|currentConstrainedOut| >= 20`, call
//    `CloseSpanWithinBudget` with a small budget to find the longest
//    completable prefix and close it, preventing runaway expressions.
// 4. Near-budget grace close: when ≤ 3 steps remain inside a span, force
//    `CloseSpanWithinBudget` to prevent unterminated final spans.
// 5. Phase 0: close any pre-existing open span on entry.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Outside-span branch (UnconstrainedStep):
//     insideConstrainedOut stays false until RenderedEndsWith fires.
//     EnterObservedConstrainedSpan sets currentConstrainedOut := [] and
//     insideConstrainedOut := true. parser.IsValidPrefix([]) holds by
//     method precondition. The implication is satisfied. ✓
//
//   Inside-span, IsCompletePrefix branch (CloseConstrainedSpan):
//     Sets insideConstrainedOut := false, making the implication vacuously
//     true; currentConstrainedOut := []. ✓
//
//   Inside-span, forced-close branch (CloseSpanWithinBudget):
//     Its postcondition directly guarantees
//     insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut). ✓
//
//   Inside-span, normal step (RepetitionPenaltyStep + AppendConstrainedToken):
//     RepetitionPenaltyStep hard-masks to parser-valid next tokens plus EOS,
//     so the returned token next satisfies IsTokenValidNext. AppendConstrainedToken
//     extends currentConstrainedOut with that token, preserving IsValidPrefix
//     by the validity guarantee of the chosen token. ✓
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//
//   Phase 0: b0 = min(avail0, 10); CloseSpanWithinBudget postcondition gives
//     |cg0| <= |generated| + b0 = |generatedPrefix| + b0; steps := b0. ✓
//
//   Outside-span, non-EOS: steps += 1, generated grows by exactly 1 token.
//     |generated|+1 <= |generatedPrefix| + (steps_old)+1 = |generatedPrefix|+steps_new. ✓
//     EnterObservedConstrainedSpan leaves generated unchanged. ✓
//
//   Outside-span, EOS/break: steps += 1, generated unchanged. ✓
//
//   Inside-span, IsCompletePrefix: CloseConstrainedSpan appends at most one
//     ">>" token; steps += 1. Invariant preserved. ✓
//
//   Inside-span, forced close: b = min(avail, 5); steps_new = steps_old + b;
//     |generated_new| <= |generated_old| + b <= |generatedPrefix| + steps_old + b
//     = |generatedPrefix| + steps_new; and steps_new <= maxSteps. ✓
//
//   Inside-span, RepetitionPenaltyStep: steps += 1, AppendConstrainedToken
//     appends exactly 1 token; |generated|+1 <= |generatedPrefix|+steps_new. ✓
//
//   EOS break inside span: steps += 1, generated unchanged. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve step by step. Wrap each computation result and the final numeric answer inside << >> delimiters. Keep each expression concise and exact, e.g., <<n * price>> or <<a + b - c>>.");

var steps: nat := 0;
var maxSpanLen: nat := 20;

// Phase 0: close any pre-existing open constrained span.
if insideConstrainedOut && steps < maxSteps {
  var avail0 : nat := maxSteps - steps;
  var b0 : nat := if avail0 < 10 then avail0 else 10;
  var cg0, ci0, cc0 := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, b0
  );
  generated := cg0;
  insideConstrainedOut := ci0;
  currentConstrainedOut := cc0;
  steps := steps + b0;
}

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      var eg, ei, ec := helpers.EnterObservedConstrainedSpan(lm, generated);
      generated := eg;
      insideConstrainedOut := ei;
      currentConstrainedOut := ec;
    }
  } else {
    // Inside constrained span.
    if parser.IsCompletePrefix(currentConstrainedOut) {
      // Span complete: close it immediately.
      var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    } else if |currentConstrainedOut| >= maxSpanLen || maxSteps - steps <= 3 {
      // Span too long or near budget end: force close with bounded budget.
      var avail : nat := maxSteps - steps;
      var b : nat := if avail < 5 then avail else 5;
      var cg, ci, cc := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, b
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + b;
    } else {
      // Normal constrained step with repetition penalty to break loops.
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.RepetitionPenaltyStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, generated, 3.0, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      }
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

cost := steps;

